     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
     */
    public int getMembershipPoints() {
        int points = 0;
        if (this.email != null && !this.email.isEmpty()) {
