     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
     */
    private int computeMembershipLevel() {
        int points = getMembershipPoints();
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
